function destroyBlock(b,collapse=false){if(b.dead)return;b.dead=true;b.mesh.visible=false;if(b.cracks)b.cracks.visible=false;broken.add(b.id);settleRubble(b);if(b.links)for(const linked of b.links){const epoch=worldEpoch;setTimeout(()=>{if(epoch===worldEpoch)destroyBlock(linked,true);},180);}const value=Math.round((b.cache?90:8+b.district*6)*(mode==='rush'?3:1)*(1+tiers[3]*.18));stone+=value;spawnDebris(b.mesh.position,collapse?11:20,b.prop?.7:1.4);number('+'+value,b.mesh.position,b.cache);if(b.cache){toast('RELIC CACHE +'+value);sound('upgrade');}for(let i=0;i<3;i++)pickups.push({p:b.mesh.position.clone(),life:1,offset:rand()*6});
// Unsupported stacks collapse into loose traversable rubble.
if(!collapse){for(const upper of blocks){if(!upper.dead&&upper.z-b.z<1.4&&Math.abs(upper.z-b.z)<1.4&&Math.abs(upper.x-b.x)<1&&upper.y>b.y&&upper.y-b.y<14){const epoch=worldEpoch;setTimeout(()=>{if(epoch===worldEpoch)destroyBlock(upper,true);},100+Math.random()*160);}}}syncBlocks();updateHUD();}
function explode(pos,power){shake=Math.max(shake,.18+power*.15);kick=.10;hitStop=.035;sound('break');const radius=2.5+tiers[1]*.62+power*1.6;let hits=0;for(const b of blocks){if(b.dead)continue;const dx=Math.max(0,Math.abs(b.x-pos.x)-b.sx*.5),dy=Math.max(0,Math.abs(b.y-pos.y)-b.sy*.5),dz=Math.max(0,Math.abs(b.z-pos.z)-b.sz*.5),dist=Math.hypot(dx,dy,dz);if(dist<radius){const damage=(26+power*85)*(1+tiers[0]*.4)*(1-dist/(radius*1.5));b.hp-=damage;hits++;if(b.hp<=0)destroyBlock(b);else{b.mesh.material=darkstone;syncBlocks();number(Math.round(damage),b.mesh.position);spawnDebris(b.mesh.position,4);}}}
const ring=mesh(new THREE.SphereGeometry(1,16,10),new THREE.MeshBasicMaterial({color:0xffd48c,transparent:true,opacity:.55,wireframe:true}),pos.x,pos.y,pos.z);projectiles.push({effect:true,mesh:ring,life:.35,radius});spawnDebris(pos,12);if(hits)lastShot=elapsed;}
function fire(power){if(forgeOpen||$('rushEnd').hidden===false)return;firstAction??=performance.now()-loadTime;actionCount++;$('hint').style.opacity=0;sound('blast',power);kick=.18+power*.08;shake=.04;const dir=new THREE.Vector3();camera.getWorldDirection(dir);const p=player.clone().add(dir.clone().multiplyScalar(1.1));const m=mesh(new THREE.IcosahedronGeometry(.13+power*.19,2),glow,p.x,p.y,p.z);const trail=mesh(new THREE.TorusGeometry(.23,.025,5,20),glow,p.x,p.y,p.z);projectiles.push({mesh:m,trail,p,dir,power,speed:22+tiers[2]*2,life:7,penetration:tiers[2],cooldown:0});}
const loadTime=0;
const branches=[['✹','Seismic force','Heavier impact','Cannon grows'],['◎','Resonance','Wider fracture','Luminous blast'],['➶','Tunneling','Piercing spheres','Chain impacts'],['⌁','Magnet','Salvage multiplier','Longer reach'],['⚒','Machinery','Autonomous rigs','Stone / second'],['↟','Mobility','Sprint · grapple · hover','Space / E / hold Space']];
function cost(i){return Math.round((i===4?90:35)*Math.pow(1.78,tiers[i]));}
function purchase(i){if(tiers[i]>=8||stone<cost(i))return false;stone-=cost(i);tiers[i]++;sound('upgrade');toast(branches[i][1].toUpperCase()+' · '+tiers[i]);updateEquipment();updateHUD();renderForge();save();return true;}
function updateEquipment(){gun.scale.setScalar(1+tiers[0]*.045);chamber.scale.setScalar(1+tiers[1]*.08);gunRings.forEach((r,i)=>r.visible=i<tiers[0]);for(const rig of rigObjects){scene.remove(rig);}rigObjects=[];for(let i=0;i<tiers[4];i++){const g=new THREE.Group();g.position.set((i%2?1:-1)*7,.15+floorHeight(-6-i*12),-6-i*12);scene.add(g);const base=new THREE.Mesh(new THREE.BoxGeometry(1.7,.5,2.2),iron);base.position.y=.3;g.add(base);const drill=new THREE.Mesh(new THREE.ConeGeometry(.6,2,12),brass);drill.rotation.x=-Math.PI/2;drill.position.set(0,1,-1);g.add(drill);for(let k=0;k<7;k++){const belt=new THREE.Mesh(new THREE.BoxGeometry(.8,.08,.32),wood);belt.position.set(0,.6,k*.4);g.add(belt);}rigObjects.push(g);}
$('movementHint').textContent=tiers[5]>=5?' · HOLD SPACE hover':tiers[5]>=3?' · E grapple':'';}
function renderForge(){const root=$('upgrades');root.innerHTML='';branches.forEach((b,i)=>{const button=document.createElement('button');button.className='upgrade';button.disabled=tiers[i]>=8;button.innerHTML=`<span class="icon">${b[0]}</span><span><strong>${b[1]}</strong><small>${i===4?tiers[i]*2+' stone / second':i===5?(tiers[i]>=5?'Hover harness':tiers[i]>=3?'Grapple harness':tiers[i]>=1?'Powered sprint':b[2]):b[2]}</small><span class="pips">${Array.from({length:8},(_,n)=>'<i class="pip '+(n<tiers[i]?'on':'')+'"></i>').join('')}</span></span><span class="cost">${tiers[i]>=8?'MAX':'⬡ '+cost(i)}</span>`;button.onclick=()=>{if(!purchase(i)){sound('tick');toast('MORE STONE');}};root.append(button);});}
function updateHUD(){$('stone').textContent=Math.floor(stone).toLocaleString();$('broken').textContent=String(broken.size).padStart(3,'0');$('powerLabel').textContent='MK '+(tiers[0]+1);}
function toggleForge(open=!forgeOpen){forgeOpen=open;$('forge').hidden=!open;if(open){charging=false;charge=0;document.exitPointerLock?.();renderForge();}}
function save(){if(mode!=='main')return;try{localStorage.setItem(saveKey,JSON.stringify({stone,tiers,broken:[...broken],player:player.toArray(),yaw,pitch,time:Date.now()}));}catch{}}
function loadMain(){if(!saved){try{saved=JSON.parse(localStorage.getItem(saveKey)||'null');}catch{}}stone=0;tiers=[0,0,0,0,0,0];broken=new Set();player.set(0,2.1,12);yaw=0;pitch=-.025;if(saved){stone=Number(saved.stone)||0;tiers=saved.tiers.map(v=>clamp(Number(v)||0,0,8));broken=new Set(saved.broken);player.fromArray(saved.player);yaw=saved.yaw||0;pitch=saved.pitch||0;stone+=Math.min(1800,Math.max(0,(Date.now()-saved.time)/1000))*tiers[4]*2;}for(const b of blocks){b.dead=broken.has(b.id);b.mesh.visible=!b.dead;if(b.cracks)b.cracks.visible=!b.dead;b.hp=b.maxHp;}syncBlocks();updateEquipment();updateHUD();}
function setMode(next){worldEpoch++;settledRubble.count=0;if(mode==='main'){save();try{saved=JSON.parse(localStorage.getItem(saveKey));}catch{}}mode=next;projectiles.forEach(p=>{scene.remove(p.mesh);if(p.trail)scene.remove(p.trail);});projectiles=[];particles=[];pickups=[];charging=false;charge=0;velocityY=0;currentDistrict=0;$('rushEnd').hidden=true;toggleForge(false);if(mode==='rush'){stone=0;tiers=[3,3,2,2,0,5];broken=new Set();player.set(0,2.1,5);yaw=0;pitch=0;rushLeft=300;for(const b of blocks){b.dead=false;b.hp=b.maxHp;b.mesh.visible=true;if(b.cracks)b.cracks.visible=true;}toast('FIVE MINUTES. BREAK EVERYTHING.');updateEquipment();updateHUD();}else loadMain();syncBlocks();$('mainMode').classList.toggle('active',mode==='main');$('rushMode').classList.toggle('active',mode==='rush');}
$('forgeButton').onclick=()=>toggleForge();$('closeForge').onclick=()=>toggleForge(false);$('mainMode').onclick=()=>setMode('main');$('rushMode').onclick=()=>setMode('rush');$('again').onclick=()=>setMode('rush');$('return').onclick=()=>setMode('main');$('audio').onclick=()=>{muted=!muted;$('audio').textContent=muted?'♪ ×':'♫';if(!muted)sound('tick');};
let quality='medium';function applyQuality(q){quality=q==='auto'?((navigator.hardwareConcurrency||4)<=4?'low':'medium'):q;stoneQuality.value=quality==='low'?0:1;renderer.setPixelRatio(quality==='low'?.6:quality==='medium'?Math.min(devicePixelRatio,1.25):Math.min(devicePixelRatio,1.75));renderer.setSize(innerWidth,innerHeight);dust.visible=quality!=='low';}applyQuality('auto');$('quality').onchange=e=>applyQuality(e.target.value);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
let lockTime=0;document.addEventListener('pointerlockchange',()=>lockTime=performance.now());
const canvas=$('world');canvas.addEventListener('mousedown',e=>{if(e.button!==0||forgeOpen)return;if(document.pointerLockElement!==canvas)canvas.requestPointerLock?.();charging=true;sound('tick');});window.addEventListener('mouseup',e=>{if(e.button===0&&charging){fire(charge);charging=false;charge=0;}});window.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&performance.now()-lockTime>150&&Math.abs(e.movementX)<120&&Math.abs(e.movementY)<120){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0022,-1.42,1.42);}});window.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(['Tab','Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Tab'&&!e.repeat)toggleForge();if(e.code==='Escape')toggleForge(false);if(e.code==='KeyE'&&tiers[5]>=3&&!e.repeat)grapple();});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false;charging=false;charge=0;save();});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('beforeunload',save);
const ray=new THREE.Raycaster();function grapple(){camera.updateMatrixWorld();ray.setFromCamera(new THREE.Vector2(),camera);const hits=ray.intersectObjects(scene.children,true).filter(h=>h.distance>3&&h.distance<40&&h.object!==gun);if(hits.length){grappling=hits[0].point.clone().add(new THREE.Vector3(0,1,0));toast('GRAPPLE');sound('tick');}}
let touchLast=null;canvas.addEventListener('touchstart',e=>{e.preventDefault();touchLast={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:false});canvas.addEventListener('touchmove',e=>{e.preventDefault();if(touchLast){yaw-=(e.touches[0].clientX-touchLast.x)*.006;pitch=clamp(pitch-(e.touches[0].clientY-touchLast.y)*.006,-1.4,1.4);touchLast={x:e.touches[0].clientX,y:e.touches[0].clientY};}},{passive:false});for(const [id,key] of [['touchMove','KeyW'],['touchJump','Space']]){$(id).onpointerdown=e=>{e.preventDefault();keys[key]=true;$(id).setPointerCapture(e.pointerId);};$(id).onpointerup=$(id).onpointercancel=()=>keys[key]=false;}$('touchFire').onpointerdown=e=>{e.preventDefault();charging=true;$('touchFire').setPointerCapture(e.pointerId);sound('tick');};$('touchFire').onpointerup=()=>{if(charging)fire(charge);charging=false;charge=0;};
function collides(p){if(Math.abs(p.x)>11.9||p.z>19||p.z<-183)return true;return blocks.some(b=>!b.dead&&Math.abs(p.x-b.x)<b.sx*.5+.35&&Math.abs(p.z-b.z)<b.sz*.5+.35&&p.y-1.8<b.y+b.sy*.5&&p.y>b.y-b.sy*.5);}
function movePlayer(dt){if(forgeOpen||!$('rushEnd').hidden)return;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);const pads=navigator.getGamepads?.();if(pads?.[0]){const p=pads[0];forward-=Math.abs(p.axes[1])>.15?p.axes[1]:0;side+=Math.abs(p.axes[0])>.15?p.axes[0]:0;yaw-=(Math.abs(p.axes[2])>.15?p.axes[2]:0)*dt*2;pitch=clamp(pitch-(Math.abs(p.axes[3])>.15?p.axes[3]:0)*dt*1.6,-1.4,1.4);const trigger=p.buttons[7].pressed;if(trigger&&!charging)charging=true;else if(!trigger&&charging){fire(charge);charging=false;charge=0;}keys.Space=p.buttons[0].pressed;}
const norm=Math.max(1,Math.hypot(forward,side)),speed=(keys.ShiftLeft?8+tiers[5]*.45:5.2)*(mode==='rush'?1.15:1);const v=new THREE.Vector3((side*Math.cos(yaw)-forward*Math.sin(yaw))/norm,0,(-forward*Math.cos(yaw)-side*Math.sin(yaw))/norm).multiplyScalar(speed*dt);let next=player.clone();next.x+=v.x;if(!collides(next))player.x=next.x;next.copy(player);next.z+=v.z;if(!collides(next))player.z=next.z;
if(keys.Space&&grounded){velocityY=7+tiers[5]*.5;grounded=false;sound('tick');}hover=tiers[5]>=5&&keys.Space&&!grounded;if(hover)velocityY=Math.min(velocityY+22*dt,4.5);else velocityY-=20*dt;next.copy(player);next.y+=velocityY*dt;if(!collides(next))player.y=next.y;else if(velocityY>0)velocityY=0;else{velocityY=0;grounded=true;}if(player.y<2.1+floorHeight(player.z)){player.y=2.1+floorHeight(player.z);velocityY=0;grounded=true;}player.y=Math.min(player.y,16+floorHeight(player.z));
if(grappling){const delta=grappling.clone().sub(player);if(delta.length()<2)grappling=null;else{const step=delta.normalize().multiplyScalar(18*dt);next.copy(player).add(step);if(!collides(next)){player.copy(next);velocityY=0;}else grappling=null;}}
if(hover&&Math.random()<.3)spawnDebris(player.clone().add(new THREE.Vector3(0,-1.9,0)),1,.4);
const district=clamp(Math.floor((-player.z+16)/36),0,4);if(district!==currentDistrict){currentDistrict=district;$('district').textContent=String(district+1).padStart(2,'0')+' / '+names[district];$('discovery').querySelector('strong').textContent=names[district];$('discovery').style.opacity=1;setTimeout(()=>$('discovery').style.opacity=0,3200);sound('upgrade');}$('depth').textContent='DEPTH '+String(Math.max(0,Math.floor((12-player.z)*1.8))).padStart(3,'0')+' m';return Math.hypot(v.x,v.z);}
let fps=60,frameCount=0,fpsTime=0,miningTimer=0,autosave=0;const pickupMesh=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(.065,0),glow,350);scene.add(pickupMesh);pickupMesh.frustumCulled=false;
function tick(dt){elapsed+=dt;const walk=movePlayer(dt)||0;camera.position.copy(player);camera.position.y+=walk>0&&grounded?Math.sin(elapsed*12)*.035:Math.sin(elapsed*1.6)*.008;camera.rotation.set(pitch+(Math.random()-.5)*shake-kick,yaw+(Math.random()-.5)*shake,Math.sin(elapsed*2)*.0006);shake*=Math.exp(-dt*10);kick*=Math.exp(-dt*12);
if(charging){charge=Math.min(1,charge+dt*.85);muzzle.visible=true;muzzle.scale.setScalar(.5+charge*1.6);muzzle.rotation.y+=dt*4;shotLight.intensity=charge*4;$('reticle').style.transform=`translate(-50%,-50%) scale(${1+charge*.5})`;$('reticle').querySelector('span').style.opacity=charge;}else{muzzle.visible=false;shotLight.intensity*=.8;$('reticle').style.transform='translate(-50%,-50%)';$('reticle').querySelector('span').style.opacity=0;}$('chargeFill').style.width=charge*100+'%';gun.position.y=-.60+Math.sin(elapsed*8)*walk*.3;gun.position.z=-1.14+kick*.8;chamber.material.color.setHSL(.10,.8,.4+Math.sin(elapsed*3)*.07+charge*.2);
for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;if(p.effect){p.mesh.scale.setScalar((.35-p.life)*p.radius*5);p.mesh.material.opacity=p.life*.7;}else{const old=p.p.clone();p.p.addScaledVector(p.dir,p.speed*dt);p.mesh.position.copy(p.p);p.mesh.rotation.x+=dt*3;p.trail.position.copy(p.p);p.trail.lookAt(p.p.clone().add(p.dir));p.trail.scale.setScalar(1+Math.sin(elapsed*20)*.1);p.cooldown-=dt;
if(p.cooldown<=0){ray.set(old,p.dir);ray.far=p.speed*dt+.3;const hit=ray.intersectObjects(blocks.filter(b=>!b.dead).map(b=>b.mesh),false)[0];if(hit||p.p.y<floorHeight(p.p.z)+.25||Math.abs(p.p.x)>12.5||p.p.z<-184){const at=hit?hit.point:p.p.clone();explode(at,p.power);if(p.penetration>0&&hit){p.penetration--;p.cooldown=.22;p.p.addScaledVector(p.dir,1.8);}else p.life=0;}}}
if(p.life<=0){scene.remove(p.mesh);if(p.effect){p.mesh.geometry.dispose();p.mesh.material.dispose();}if(p.trail){scene.remove(p.trail);p.trail.geometry.dispose();}projectiles.splice(i,1);}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=12*dt;p.p.addScaledVector(p.v,dt);if(p.p.y<floorHeight(p.p.z)+p.s){p.p.y=floorHeight(p.p.z)+p.s;p.v.y*=-.28;p.v.x*=.8;p.v.z*=.8;}p.r.x+=dt*3;p.r.z+=dt*2;if(p.life<=0)particles.splice(i,1);}debrisMesh.count=particles.length;particles.forEach((p,i)=>{dummy.position.copy(p.p);dummy.rotation.set(p.r.x,p.r.y,p.r.z);dummy.scale.setScalar(p.s*Math.min(1,p.life*2));dummy.updateMatrix();debrisMesh.setMatrixAt(i,dummy.matrix);});debrisMesh.instanceMatrix.needsUpdate=true;
for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.life-=dt*.8;p.p.lerp(player,.03+dt*(1+tiers[3]));if(p.life<0)pickups.splice(i,1);}pickupMesh.count=Math.min(350,pickups.length);pickups.slice(0,350).forEach((p,i)=>{dummy.position.copy(p.p);dummy.rotation.set(elapsed,0,elapsed);dummy.scale.setScalar(1);dummy.updateMatrix();pickupMesh.setMatrixAt(i,dummy.matrix);});pickupMesh.instanceMatrix.needsUpdate=true;
dust.position.y=Math.sin(elapsed*.1)*.3;rigObjects.forEach((g,i)=>{g.children[1].rotation.y+=dt*5;for(let j=2;j<g.children.length;j++)g.children[j].position.z=((elapsed*.7+j*.4)%2.8)-.4;});
miningTimer+=dt;if(miningTimer>1){miningTimer=0;if(tiers[4]){stone+=tiers[4]*2;updateHUD();}}
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').style.opacity=0;}if(mode==='rush'&&$('rushEnd').hidden){rushLeft=Math.max(0,rushLeft-dt);$('rushClock').textContent=Math.floor(rushLeft/60)+':'+String(Math.floor(rushLeft%60)).padStart(2,'0');if(rushLeft<=0){$('rushScore').textContent=broken.size+' fractures';$('rushEnd').hidden=false;document.exitPointerLock?.();}}else if(mode==='main')$('rushClock').textContent='';
autosave+=dt;if(autosave>8){autosave=0;save();}}
loadMain();updateHUD();let prev=performance.now();function frame(now){requestAnimationFrame(frame);const rawDt=(now-prev)/1000,dt=Math.min(rawDt,.25);prev=now;fpsTime+=rawDt;frameCount++;if(fpsTime>.5){fps=frameCount/fpsTime;frameCount=0;fpsTime=0;}if(hitStop>0)hitStop-=dt;else tick(dt);renderer.render(scene,camera);}requestAnimationFrame(frame);
